import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"爻數第十三","description":"杭氏易學 - 爻數第十三","frontmatter":{"title":"爻數第十三","description":"杭氏易學 - 爻數第十三"},"headers":[],"relativePath":"classics/hangshi/014.md","filePath":"classics/hangshi/014.md"}'),i={name:"classics/hangshi/014.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"爻數第十三",tabindex:"-1"},[r("爻數第十三 "),e("a",{class:"header-anchor",href:"#爻數第十三","aria-label":"Permalink to “爻數第十三”"},"​")],-1),e("p",null,"六位成章，陰陽迭運。位虛爻實，奇偶相生。積爻成卦，數亦相因。復一坎子，震未出用，故曰“復小”。臨二醜寅，坤兌數十，故曰“臨大”。陰爻無始，陽爻無終。陰陽首尾，往復不窮。故數盡十位，而爻十二。天五地六，以定甲子。八宮六世，三四相重。飛伏隱見，變化無盡，而無不可以數稽之。故爻位與象義既明，必徵之於數，而後是非可辨也。",-1),e("p",null,"陰陽六爻，皆指乾坤。乾父坤母，六子卦皆分乾坤之爻，各得乾坤之一體。象數變化，皆不離其宗。鄭氏爻辰，即以乾坤兩卦，分十二辰。鍾度聲律，亦各以此數交錯，相生相合，而各得其應得之數。《節?彖傳》曰：“節以制度。君子以制度數，議德行。”若由後儒之說，德行與度數何涉？宋人性理諸書，汗牛充棟，所謂表裡精粗無不到者，獨無度數以節之。陰陽五行，皆鑿空之談。而所謂異端者，若老子若墨子若莊列諸子，及釋家大乘經典，其言之精者，各有數度，各有法象之可徵。皆所謂法言，非任意空談可擬也。故明乎八卦之象數，明乎《彖》、《象》十翼無一辭一字之不合象數，而後三代兩漢文章之度數可辨。後世之書是否合於度數者，亦皆可辨矣 【揚子云知《易》象數理之精，恐後人不解，乃苦心焦思作《太玄》，以明數。作《法言》，以仿《論語》。非擬經侮聖也，其意欲人之由淺入深，因《太玄》而進於《易》。因《法言》而悟《論語》之法度，用心良苦。乃後人並《太玄》不能解，何有於《易》？讀《論語註疏》，更蔑視《法言》。又以朱子綱目“莽大夫”三字作揚雄定評，後世遂存以人廢言之成見。《太玄》、《法言》乃真成覆醬瓶之物。《太玄》、《法言》不足惜，《易經》、《論語》法象數度之不明，貽人心世道之優，良足痛焉！】 。",-1),e("p",null,"乾簡坤易，象數著明。象由微而知著，數執簡以御繁。太極由是生兩儀，生四象，生八卦，以生六十四卦。而六十四卦仍以一“是 【《未濟?上六?象》曰“有孚失是”，為全經最後之一字。】 ”返本還原。故欲求其“是”，當求諸始。乾坤《易》之始，六爻乾坤之始，一畫開天又六爻之始。故言卦數者，必自爻數始。",-1)])])}const f=s(i,[["render",l]]);export{_ as __pageData,f as default};
